insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_101_v1'
from (values
('127.758.d.1.A',3,'A student studies how detectives gather facts, interview people and build a case for prosecutors. This analyzes the field of:','["criminal investigations", "interior design", "urban planning", "tax preparation"]'::jsonb,0,'Investigation seeks facts to identify offenders.','original'),
('127.758.d.1.A',4,'The main purpose of a criminal investigation is to:','["entertain the public", "gather facts to determine what happened and who is responsible", "punish suspects before trial", "avoid evidence"]'::jsonb,1,'Investigations collect facts.','original'),
('127.758.d.1.B',3,'Two detectives are compared: one is patient, detail-oriented and objective, the other jumps to conclusions. This compares characteristics of:','["a good salesperson", "a talented chef", "an effective investigator", "a skilled pilot"]'::jsonb,2,'Effective investigators are objective and thorough.','original'),
('127.758.d.1.B',4,'Which trait most helps an investigator build a reliable case?','["carelessness", "guessing", "bias and haste", "objectivity and attention to detail"]'::jsonb,3,'Objectivity avoids tunnel vision.','original'),
('127.758.d.1.C',3,'The first officer arrives, aids the injured, secures the scene and notes who was present. This examines the:','["preliminary investigation", "parole review", "final trial", "sentencing"]'::jsonb,0,'Initial response begins the case.','original'),
('127.758.d.1.C',4,'One of the first duties of the officer arriving at a crime scene is to:','["clean up", "protect life and secure the scene", "collect souvenirs", "leave quickly"]'::jsonb,1,'Safety and preservation come first.','original'),
('127.758.d.1.D',3,'After the scene is processed, detectives re-interview witnesses, canvass the area and check records. This researches:','["menu planning", "school scheduling", "follow-up procedures for an investigation", "vacation planning"]'::jsonb,2,'Follow-up develops new leads.','original'),
('127.758.d.1.D',4,'A follow-up investigation often includes:','["ending all work", "destroying notes", "ignoring leads", "re-interviewing witnesses and reviewing lab results"]'::jsonb,3,'It builds on preliminary findings.','original'),
('127.758.d.1.E',3,'A detective tracks how cooperation among patrol officers, lab analysts and prosecutors affected a case. This evaluates:','["interrelationships among individuals involved in an investigation", "weather patterns", "rivalries in sports", "road conditions"]'::jsonb,0,'Teamwork affects outcomes.','original'),
('127.758.d.1.E',4,'Strong working relationships with prosecutors help investigators by:','["hiding evidence", "improving case preparation and communication", "slowing cases", "reducing accuracy"]'::jsonb,1,'Coordination strengthens cases.','original'),
('127.758.d.2.A',3,'An investigator writes down times, names and observations at the scene so details are not forgotten. This explains the use of:','["menus", "billboards", "field notes", "playlists"]'::jsonb,2,'Notes preserve facts.','original'),
('127.758.d.2.A',4,'Field notes are valuable because they:','["replace evidence", "avoid documentation", "entertain jurors", "preserve accurate details for reports and court"]'::jsonb,3,'Notes support testimony.','original'),
('127.758.d.2.B',3,'A trainee records the date, location, weather and who was present before describing each item. This demonstrates when, what, where and how to take:','["investigative notes", "travel plans", "lecture slides", "recipes"]'::jsonb,0,'Note content follows a pattern.','original'),
('127.758.d.2.B',4,'Which information belongs in field notes?','["guesses about guilt", "time, location and observed facts", "personal opinions only", "jokes"]'::jsonb,1,'Record facts, not conclusions.','original'),
('127.758.d.2.C',3,'The investigator writes legibly in ink, avoids erasing and corrects mistakes with a single line. This shows how to:','["destroy notes", "hide mistakes", "effectively take notes during an investigation", "use pencil only"]'::jsonb,2,'Notes must be clear and reliable.','original'),
('127.758.d.2.C',4,'If an error is made in field notes, the investigator should:','["erase it", "use correction fluid", "tear out the page", "draw a single line through it and initial the change"]'::jsonb,3,'Original text stays visible.','original'),
('127.758.d.2.D',3,'A team debates whether photographs show scene detail well but may miss smell, sound or scale. This distinguishes advantages and disadvantages of:','["photographs and videos in an investigation", "written wills", "spoken reports", "signed notes"]'::jsonb,0,'Photos capture detail but have limits.','original'),
('127.758.d.2.D',4,'A disadvantage of relying only on photographs is that they:','["are always inadmissible", "may not show scale, depth or everything present", "cost nothing", "cannot be stored"]'::jsonb,1,'Photos have limits.','original'),
('127.758.d.2.E',3,'Before shooting, an investigator plans overall, mid-range and close-up shots with a scale in each close-up. This plans use of:','["sports photography", "fashion photography", "digital investigative photography", "portrait photography"]'::jsonb,2,'Plan to document systematically.','original'),
('127.758.d.2.E',4,'A scale is placed beside an item in a close-up photo to:','["hide the item", "add color", "block the view", "show the true size of the item"]'::jsonb,3,'Scale enables measurement.','original'),
('127.758.d.2.F',3,'A photographer takes wide, medium and close-up pictures of a scene in a logical order and logs each frame. This organizes:','["a photographic sequence of a crime scene", "a school yearbook", "a wedding album", "a travel album"]'::jsonb,0,'Sequences tell the scene''s story.','original'),
('127.758.d.2.F',4,'A common photographic sequence at a scene moves from:','["one angle only", "overall views to mid-range to close-ups", "close-ups only", "random shots"]'::jsonb,1,'Overall to detail.','original'),
('127.758.d.2.G',3,'A student studies a series of scene photos, infers what happened and predicts what else may be found. This is the skill of:','["guessing wildly", "avoiding detail", "analyzing and evaluating photographs to make inferences", "ignoring images"]'::jsonb,2,'Photos can support reasoning.','original'),
('127.758.d.2.G',4,'An inference from a crime scene photo should be based on:','["hunches alone", "a coin toss", "rumors", "visible evidence and logical reasoning"]'::jsonb,3,'Inferences need support.','original'),
('127.758.d.2.H',3,'An attorney asks whether photos are fair, accurate and relevant before showing them to a jury. This relates to:','["admissibility of photographs in court", "film reviews", "art contests", "prize rules"]'::jsonb,0,'Photos must be authenticated.','original'),
('127.758.d.2.H',4,'For a photograph to be admitted as evidence, a witness generally must testify that it:','["was edited for clarity", "fairly and accurately depicts the scene", "is artistic", "was taken years later"]'::jsonb,1,'Foundation is required.','original'),
('127.758.d.3.A',3,'Before drawing, a trainee walks the scene, notes the layout and decides on a plan for the sketch. This reflects:','["skipping steps", "drawing at random", "planning and observation prior to sketching a crime scene", "ignoring the scene"]'::jsonb,2,'Observation precedes the sketch.','original'),
('127.758.d.3.A',4,'Before sketching a scene, the investigator should first:','["erase evidence", "leave the scene", "print photos", "observe and plan the layout"]'::jsonb,3,'Plan first.','original'),
('127.758.d.3.B',3,'A sketch shows a compass direction, a scale, a legend and measured distances to key items. These are:','["elements of a crime scene sketch", "parts of a menu", "parts of a ticket", "parts of a poster"]'::jsonb,0,'Sketches include measurements and keys.','original'),
('127.758.d.3.B',4,'A legend on a crime scene sketch explains:','["the artist''s name only", "the symbols and items shown", "the weekly schedule", "the weather"]'::jsonb,1,'Legends decode symbols.','original'),
('127.758.d.3.C',3,'A trainee measures an item''s distance from two fixed walls to place it on the drawing. This develops a sketch using:','["music", "colors", "coordinates or measurements from fixed points", "guesses"]'::jsonb,2,'Fixed points anchor evidence.','original'),
('127.758.d.3.C',4,'Measurements for a scene sketch are best taken from:','["other evidence", "changing objects", "movable furniture", "fixed, permanent reference points"]'::jsonb,3,'Fixed points do not move.','original'),
('127.758.d.3.D',3,'An investigator writes a narrative of the room''s layout, evidence positions and conditions as the sketch is made. This summarizes the scene by:','["taking notes and recording details", "ignoring details", "copying a movie", "waiting a week"]'::jsonb,0,'Notes complement sketches.','original'),
('127.758.d.3.D',4,'Notes taken with a sketch should describe:','["guesses about motive", "conditions, items and observed details", "unrelated chatter", "personal feelings"]'::jsonb,1,'Record facts.','original'),
('127.758.d.3.E',3,'A supervisor reviews the rough sketch for missing measurements and mislabeled items. This evaluates:','["the room''s decor", "the artist''s fame", "the accuracy and completeness of a crime scene sketch", "the paper quality"]'::jsonb,2,'Review catches errors.','original'),
('127.758.d.3.E',4,'Reviewing a rough sketch helps ensure that it is:','["humorous", "colorful", "oversized", "accurate and complete"]'::jsonb,3,'Quality control.','original'),
('127.758.d.3.F',3,'A rough sketch is later redrawn neatly to scale using drafting tools. This describes the:','["final sketch or finished scale drawing", "first draft only", "phone note", "verbal report"]'::jsonb,0,'Final drawings are scaled and neat.','original'),
('127.758.d.3.F',4,'A finished scale drawing differs from a rough sketch because it is:','["hand-waved", "neat and drawn to scale", "unlabeled", "messy"]'::jsonb,1,'Final drawings are polished.','original'),
('127.758.d.4.A',3,'A report writer sorts facts, arranges them in order and chooses clear wording. This distinguishes organizing information, structuring the narrative and:','["hiding results", "omitting facts", "writing the report in clear language", "guessing"]'::jsonb,2,'Good reports are organized and clear.','original'),
('127.758.d.4.A',4,'A well-structured investigative narrative should be:','["vague", "opinion-based", "scrambled", "chronological, clear and factual"]'::jsonb,3,'Order and clarity matter.','original'),
('127.758.d.4.B',3,'A prosecutor, a supervisor and a defense attorney may all rely on an officer''s written account. This shows the importance and uses of:','["investigative reports", "maps", "brochures", "recipes"]'::jsonb,0,'Reports support decisions and testimony.','original'),
('127.758.d.4.B',4,'Investigative reports are used to:','["replace evidence", "document facts for prosecution, supervision and court", "hide facts", "decorate offices"]'::jsonb,1,'Reports are official records.','original'),
('127.758.d.4.C',3,'A review finds reports that skip details, include opinions or contain misspellings. This analyzes:','["common melodies", "common recipes", "common problems with investigative reports", "common routes"]'::jsonb,2,'Reports can be incomplete or biased.','original'),
('127.758.d.4.C',4,'A common problem in weak investigative reports is:','["perfect order", "too much accuracy", "complete facts", "missing or unclear details"]'::jsonb,3,'Gaps weaken reports.','original'),
('127.758.d.4.D',3,'An officer dictates observations into a recorder at the scene for later transcription. This researches ways to:','["record and dictate for future report writing", "lose details", "erase evidence", "avoid writing"]'::jsonb,0,'Dictation aids later writing.','original'),
('127.758.d.4.D',4,'A benefit of dictating notes at the scene is that:','["it avoids documentation", "details are captured while fresh", "details are lost", "it replaces the report"]'::jsonb,1,'Fresh memory is best.','original'),
('127.758.d.4.E',3,'One report is handwritten at the scene and another typed into a computer system. These demonstrate different ways to:','["avoid reports", "forget reports", "write a report", "delay reports"]'::jsonb,2,'Reports may be handwritten or computerized.','original'),
('127.758.d.4.E',4,'A computerized report system generally helps by:','["preventing access", "deleting reports", "increasing errors", "storing and sharing reports efficiently"]'::jsonb,3,'Digital systems aid sharing.','original'),
('127.758.d.5.A',3,'A judge throws out evidence that police found through an illegal search. This applies the:','["exclusionary rule", "traffic rule", "jury duty rule", "tax rule"]'::jsonb,0,'Illegally obtained evidence is excluded.','original'),
('127.758.d.5.A',4,'The exclusionary rule generally prevents prosecutors from using:','["witness names", "evidence obtained in violation of the Constitution", "any evidence at all", "legally obtained evidence"]'::jsonb,1,'Protects Fourth Amendment rights.','original'),
('127.758.d.5.B',3,'An officer wants to search a suspect''s home with no emergency present. The officer typically must have a warrant or:','["a friend''s note", "a phone call", "valid consent to search", "a hunch"]'::jsonb,2,'Searches require warrant or consent.','original'),
('127.758.d.5.B',4,'A search warrant must be based on:','["a rumor", "a request from a neighbor", "a hunch", "probable cause and signed by a judge"]'::jsonb,3,'Fourth Amendment requirement.','original'),
('127.758.d.5.C',3,'An officer who reasonably suspects a person is armed quickly pats down the outer clothing. This is governed by:','["Terry v. Ohio", "Brown v. Board", "Miranda v. Arizona", "Marbury v. Madison"]'::jsonb,0,'Terry allows limited frisks.','original'),
('127.758.d.5.C',4,'A Terry pat-down is limited to:','["a car trunk search", "a search of outer clothing for weapons", "a full strip search", "any container in a home"]'::jsonb,1,'Scope is limited to weapons.','original'),
('127.758.d.5.D',3,'After lawfully arresting a suspect, the officer searches the person and the area within immediate reach. This evaluates a:','["random search", "private tour", "search incident to arrest", "trespass"]'::jsonb,2,'It protects officers and preserves evidence.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_101_v1'
from (values
('127.758.d.5.D',4,'A search incident to arrest is justified mainly to:','["delay the arrest", "hide evidence", "collect gifts", "protect officers and prevent destruction of evidence"]'::jsonb,3,'Safety and preservation.','original'),
('127.758.d.5.E',3,'Officers hear screams inside a home and enter without a warrant to help. This describes searching during:','["emergency situations or other warrantless searches", "parades", "vacations", "routine visits"]'::jsonb,0,'Exigent circumstances may allow entry.','original'),
('127.758.d.5.E',4,'Which situation may justify a warrantless entry?','["curiosity", "an urgent threat to someone''s life", "a neighbor''s complaint about noise", "boredom"]'::jsonb,1,'Exigency permits entry.','original'),
('127.758.d.5.F',3,'After an impound, the officer lists and documents the contents of the vehicle under department policy. This demonstrates how to conduct a:','["car show", "test drive", "vehicle inventory", "social visit"]'::jsonb,2,'Inventories protect property.','original'),
('127.758.d.5.F',4,'A vehicle inventory is performed mainly to:','["avoid paperwork", "search for secrets", "delay towing", "protect the owner''s property and the agency from claims"]'::jsonb,3,'Administrative purpose.','original'),
('127.758.d.6.A',3,'A student studies the early case that allowed warrantless car searches because vehicles can be moved. This analyzes the precedent from:','["Carroll v. United States", "Terry v. Ohio", "Miranda v. Arizona", "Mapp v. Ohio"]'::jsonb,0,'Carroll created the automobile exception.','original'),
('127.758.d.6.A',4,'The automobile exception generally lets officers search a vehicle without a warrant when they have:','["no reason", "probable cause", "a friend''s request", "a hunch"]'::jsonb,1,'Mobility plus probable cause.','original'),
('127.758.d.6.B',3,'Trainees divide a simulated scene into a grid and search each section methodically. This demonstrates a:','["skipped search", "random glance", "systematic search for physical evidence", "casual walk"]'::jsonb,2,'Grid, strip and spiral methods exist.','original'),
('127.758.d.6.B',4,'A search pattern that moves through a scene in parallel lines is the:','["guess method", "random method", "skip method", "strip or line method"]'::jsonb,3,'Strip search pattern.','original'),
('127.758.d.6.C',3,'Trainees practice searching a building, a vehicle, a suspect and a body with different safety rules. This demonstrates how to conduct:','["building, vehicle, suspect and dead body searches", "library searches", "web searches", "picnic searches"]'::jsonb,0,'Each requires distinct procedures.','original'),
('127.758.d.6.C',4,'A key rule when searching a suspect is to:','["skip gloves", "follow safety procedures and document what is found", "ignore officer safety", "search carelessly"]'::jsonb,1,'Safe, documented searches.','original'),
('127.758.d.6.D',3,'A K-9 handler walks a trained dog around a parked vehicle to detect narcotic odor. This explains how police canines are used to:','["carry mail", "guard livestock", "conduct legal searches", "entertain crowds"]'::jsonb,2,'Canines detect odors.','original'),
('127.758.d.6.D',4,'A trained police canine alerting to a vehicle may provide:','["no useful information", "a sentence", "a verdict", "probable cause for a further search"]'::jsonb,3,'A reliable alert can support probable cause.','original'),
('127.758.d.7.A',3,'A scene tech photographs and collects items, while a detective interviews witnesses and a prosecutor weighs charges. This compares the roles of:','["crime scene investigators, detectives and prosecutors", "pilots and crew", "chefs and servers", "referees and coaches"]'::jsonb,0,'Each role has distinct duties.','original'),
('127.758.d.7.A',4,'A crime scene investigator is mainly responsible for:','["deciding guilt", "documenting and collecting physical evidence", "hiring jurors", "sentencing"]'::jsonb,1,'CSIs process the scene.','original'),
('127.758.d.7.B',3,'One student photographs, another measures and another logs evidence during a mock scene exercise. This demonstrates the ability to:','["work alone", "hide tasks", "work as a member of a team", "avoid cooperation"]'::jsonb,2,'Scenes require teamwork.','original'),
('127.758.d.7.B',4,'Effective crime scene teams rely on:','["competition", "secrecy", "random tasks", "clear roles and communication"]'::jsonb,3,'Coordination prevents mistakes.','original'),
('127.758.d.7.C',3,'During a mock burglary scene, a trainee spots a footprint, a fiber and a discarded glove. This is the ability to:','["discover and recognize evidence", "ignore evidence", "destroy evidence", "guess evidence"]'::jsonb,0,'Observe carefully.','original'),
('127.758.d.7.C',4,'Before touching any evidence, an investigator should first:','["clean it", "document it where it is found", "pick it up", "move it"]'::jsonb,1,'Document in place.','original'),
('127.758.d.7.D',3,'A student applies the definition of burglary to decide what to search for and what to seize. This applies:','["recipes", "schedules", "the elements of criminal law that guide search and seizure", "poems"]'::jsonb,2,'Law guides what evidence matters.','original'),
('127.758.d.7.D',4,'Knowing the elements of an offense helps investigators:','["avoid evidence", "skip photos", "guess motives", "identify evidence that proves each element"]'::jsonb,3,'Evidence maps to elements.','original'),
('127.758.d.7.E',3,'Each person who handles an exhibit signs a log with date and time. This outlines the:','["chain-of-custody procedure", "travel schedule", "seating chart", "menu"]'::jsonb,0,'Chain of custody tracks handling.','original'),
('127.758.d.7.E',4,'Chain of custody is important because it:','["replaces testimony", "shows evidence was handled and preserved properly", "hides evidence", "makes evidence heavier"]'::jsonb,1,'Integrity is proven.','original'),
('127.758.d.7.F',3,'The tech photographs an item, bags it, seals it and initials the label. This demonstrates techniques for collecting, marking and:','["discarding evidence", "trading evidence", "packaging evidence", "losing evidence"]'::jsonb,2,'Proper packaging protects it.','original'),
('127.758.d.7.F',4,'Biological evidence like a damp cloth should generally be packaged in:','["airtight plastic bags", "aluminum foil", "glass jars sealed wet", "paper bags"]'::jsonb,3,'Paper lets moisture escape.','original'),
('127.758.d.7.G',3,'A tech uses video to walk through a scene and still photos for key items. This explains the use of:','["video and still photography to present a scene", "radio broadcasts", "songs", "paintings"]'::jsonb,0,'Both document the scene.','original'),
('127.758.d.7.G',4,'Video of a scene is helpful because it:','["alters the scene", "shows spatial relationships and layout", "replaces the report", "removes evidence"]'::jsonb,1,'Video gives context.','original'),
('127.758.d.7.H',3,'A prosecutor shows jurors an exhibit and a witness explains where it was found. This analyzes the use of:','["prizes in a game", "props in a movie", "evidence in a court of law", "costumes in a play"]'::jsonb,2,'Evidence supports arguments.','original'),
('127.758.d.7.H',4,'Evidence is more likely to be admitted if it is:','["altered", "unlabeled", "rumored", "relevant and properly authenticated"]'::jsonb,3,'Relevance and authentication.','original'),
('127.758.d.8.A',3,'A lab tech collects tiny paint chips, glass fragments and fibers from a hit-and-run scene. This demonstrates processing:','["trace evidence", "large vehicles", "whole buildings", "bulk furniture"]'::jsonb,0,'Trace evidence is small transferred material.','original'),
('127.758.d.8.A',4,'Trace evidence is best described as:','["large weapons", "small materials transferred between people, objects or places", "written notes", "audio only"]'::jsonb,1,'Locard''s exchange principle.','original'),
('127.758.d.8.B',3,'An examiner compares a plaster cast from a scene with a suspect''s sneaker sole. This identifies:','["voice tone", "eye color", "shoe and tire impressions", "finger length"]'::jsonb,2,'Impressions are compared for class and wear.','original'),
('127.758.d.8.B',4,'Wear patterns on a shoe sole can help link a shoe to an impression because they are:','["invisible", "random every day", "identical in all shoes", "unique to that shoe"]'::jsonb,3,'Individual characteristics.','original'),
('127.758.d.8.C',3,'Radial and concentric cracks in a broken window are examined to see which side was hit first. This determines the:','["direction of a projectile through glass", "price of the glass", "color of the glass", "age of the glass"]'::jsonb,0,'Fracture patterns show entry direction.','original'),
('127.758.d.8.C',4,'A projectile that passes through glass leaves a cone-shaped hole that is wider on the:','["bottom", "exit side", "entry side", "top"]'::jsonb,1,'The crater is wider on exit.','original'),
('127.758.d.8.D',3,'A forensic dentist examines a pattern of marks left in a victim''s skin. This analyzes:','["ink stains", "tool marks only", "bite marks", "paint chips"]'::jsonb,2,'Odontology compares dentition.','original'),
('127.758.d.8.D',4,'Bite mark analysis compares the injury pattern with a suspect''s:','["fingerprints", "footwear", "handwriting", "teeth"]'::jsonb,3,'Dental comparison.','original'),
('127.758.d.8.E',3,'Under a microscope, a hair shows a cuticle, cortex and medulla. This compares microscopic characteristics of:','["human and animal hair", "soil and sand", "glass and plastic", "paper and cloth"]'::jsonb,0,'Hair structure helps identification.','original'),
('127.758.d.8.E',4,'Which layer of a hair is the outermost scale layer?','["medulla", "cuticle", "cortex", "root"]'::jsonb,1,'The cuticle covers the hair.','original'),
('127.758.d.8.F',3,'A lab separates cotton and wool from nylon and polyester at a scene. This differentiates:','["notes and tones", "liquids and gases", "natural and synthetic fibers", "metals and plastics"]'::jsonb,2,'Fiber type aids comparison.','original'),
('127.758.d.8.F',4,'An example of a natural fiber is:','["polyester", "nylon", "acrylic", "wool"]'::jsonb,3,'Wool comes from animals.','original'),
('127.758.d.9.A',3,'Examiners sort prints into groups that curve up, loop back or spiral in circles. This compares the three major patterns of:','["arches, loops and whorls", "bars, ridges and holes", "squares, circles and lines", "dots, dashes and blanks"]'::jsonb,0,'The three basic fingerprint patterns.','original'),
('127.758.d.9.A',4,'The most common fingerprint pattern is the:','["whorl", "loop", "arch", "delta only"]'::jsonb,1,'Loops are most common.','original'),
('127.758.d.9.B',3,'An examiner marks places where a ridge splits in two or abruptly stops. These are fingerprint:','["stains", "colors", "minutiae such as bifurcations and ridge endings", "scars only"]'::jsonb,2,'Minutiae provide detail for comparison.','original'),
('127.758.d.9.B',4,'A ridge that divides into two branches is called a:','["whorl", "delta", "arch", "bifurcation"]'::jsonb,3,'Bifurcation is a split.','original'),
('127.758.d.9.C',3,'A bloody print, a print in soft wax and a print invisible to the eye are classified as:','["patent, plastic and latent impressions", "red, blue and green", "hot, cold and warm", "big, small and medium"]'::jsonb,0,'Types of fingerprint impressions.','original'),
('127.758.d.9.C',4,'A latent print is one that is:','["made in blood", "not visible to the naked eye", "clearly visible", "pressed in clay"]'::jsonb,1,'Latent = hidden.','original'),
('127.758.d.9.D',3,'A technician treats a paper note with a chemical that reacts with amino acids to reveal prints. This performs lifting on:','["plastic cups", "glass windows", "porous surfaces", "smooth metal"]'::jsonb,2,'Ninhydrin is used on porous items.','original'),
('127.758.d.9.D',4,'A chemical commonly used to develop latent prints on paper is:','["water", "sugar", "powder only", "ninhydrin"]'::jsonb,3,'Ninhydrin reacts with amino acids.','original'),
('127.758.d.9.E',3,'A technician dusts a glass window with powder and lifts the print with tape. This performs lifting on:','["nonporous surfaces", "paper", "untreated wood", "cardboard"]'::jsonb,0,'Powders work on smooth surfaces.','original'),
('127.758.d.9.E',4,'Fingerprint powder is typically applied with a:','["spray gun", "soft brush", "hammer", "cloth only"]'::jsonb,1,'Brush applies powder lightly.','original'),
('127.758.d.9.F',3,'A database compares an unknown print with millions on file to find possible matches. This explains the:','["library catalog", "telephone directory", "Automated Fingerprint Identification System (AFIS)", "school roster"]'::jsonb,2,'AFIS searches stored prints.','original'),
('127.758.d.9.F',4,'AFIS helps investigators by:','["destroying records", "creating prints", "replacing all witnesses", "narrowing possible matches among stored fingerprints"]'::jsonb,3,'Candidates are then verified by an examiner.','original'),
('127.758.d.9.G',3,'A trainee compares a latent lift from a scene with known inked prints from a suspect. This compares:','["impression evidence collected at a simulated scene", "menu items", "music samples", "school records"]'::jsonb,0,'Comparison links a suspect to a scene.','original'),
('127.758.d.9.G',4,'Fingerprint comparison relies on matching:','["height", "ridge details in the prints", "shoe size", "eye color"]'::jsonb,1,'Ridge detail is unique.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
