select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_101_v1'
from (values
('127.758.d.10.A',3,'An analyst studies round versus elongated stains on a wall to estimate where the blood originated and the angle. This analyzes:','["voice patterns", "clothing patterns", "bloodstain patterns", "hair patterns"]'::jsonb,2,'Shape reveals angle and direction.','original'),
('127.758.d.10.A',4,'A more elongated bloodstain generally indicates the drop struck the surface at a:','["perfect right angle", "vertical drop", "higher angle", "lower angle"]'::jsonb,3,'Lower angles produce longer stains.','original'),
('127.758.d.10.B',3,'An investigator sprays a chemical that glows blue when it contacts traces of invisible blood. This explains the method of:','["chemically identifying and locating hidden blood", "testing paper", "cleaning floors", "painting walls"]'::jsonb,0,'Luminol reacts with blood.','original'),
('127.758.d.10.B',4,'A chemical commonly used to locate latent blood at a scene is:','["sugar", "luminol", "salt", "bleach"]'::jsonb,1,'Luminol produces chemiluminescence.','original'),
('127.758.d.11.A',3,'A student traces how alcohol is taken into the blood, carried through the body and removed by the liver. This analyzes alcohol''s:','["cost, size and shape", "brand, label and age", "absorption, distribution and elimination", "color, taste and smell"]'::jsonb,2,'ADE explains BAC changes.','original'),
('127.758.d.11.A',4,'Most alcohol is eliminated from the body by the:','["bones", "skin only", "lungs only", "liver"]'::jsonb,3,'The liver metabolizes alcohol.','original'),
('127.758.d.11.B',3,'A lab analyst tests a blood sample for ethanol content using gas chromatography. This researches:','["blood alcohol laboratory procedures", "soil testing", "tire repair", "paint mixing"]'::jsonb,0,'BAC lab analysis.','original'),
('127.758.d.11.B',4,'Blood alcohol content is commonly measured and reported as:','["hours since drinking", "a percentage of alcohol in the blood", "number of drinks only", "pounds of blood"]'::jsonb,1,'BAC uses grams per 100 mL.','original'),
('127.758.d.11.C',3,'A heavy drinker may show fewer outward signs at the same blood level as a first-time drinker. This explains levels of:','["hair length", "height", "tolerance and impairment due to alcohol", "clothing size"]'::jsonb,2,'Tolerance masks outward signs.','original'),
('127.758.d.11.C',4,'Even with high tolerance, a driver with elevated BAC still has:','["perfect skills", "faster reflexes", "no impairment", "impaired reaction time and judgment"]'::jsonb,3,'Tolerance does not remove impairment.','original'),
('127.758.d.11.D',3,'A blood draw is stored in a gray-top tube, kept cool and labeled with a seal to avoid degradation. This explains precautions for:','["proper preservation of blood samples", "freezing without labels", "leaving in a hot car", "throwing away samples"]'::jsonb,0,'Preserve integrity.','original'),
('127.758.d.11.D',4,'Blood alcohol samples should be preserved by:','["mixing with water", "refrigerating them and sealing the container", "opening the tube", "leaving them in sunlight"]'::jsonb,1,'Prevents fermentation and tampering.','original'),
('127.758.d.12.A',3,'A lab tests a stain on a shirt to see whether it is blood and whether it is human. This explains crime lab procedures to determine if a stain is:','["oil only", "juice only", "blood or another body fluid", "paint or ink only"]'::jsonb,2,'Presumptive and confirmatory tests.','original'),
('127.758.d.12.A',4,'A presumptive test for blood is used to:','["replace DNA", "prove guilt", "destroy the stain", "indicate whether a stain might be blood"]'::jsonb,3,'Presumptive tests screen.','original'),
('127.758.d.12.B',3,'A lab researches ways to collect and analyze saliva, semen and other fluids found at a scene. These are methodologies for:','["other body fluids", "car fluids", "cooking oils", "lawn chemicals"]'::jsonb,0,'Different fluids need different tests.','original'),
('127.758.d.12.B',4,'DNA from body fluids is useful because it can:','["vanish quickly", "link a person to the evidence", "replace testimony", "change with age"]'::jsonb,1,'DNA is unique to individuals.','original'),
('127.758.d.13.A',3,'A chemist sorts drugs by medical use and abuse potential into Schedule I through V. This classifies substances under the:','["Traffic Code", "Tax Code", "Controlled Substances Act schedules", "School Code"]'::jsonb,2,'Schedules categorize drugs.','original'),
('127.758.d.13.A',4,'Substances placed in Schedule I are those with:','["only medical use", "no abuse potential", "over-the-counter status", "high abuse potential and no accepted medical use"]'::jsonb,3,'Schedule I is most restricted.','original'),
('127.758.d.13.B',3,'A forensic chemist uses color tests and instruments to name an unknown white powder. This identifies:','["controlled substances", "paint colors", "cleaning products", "cooking ingredients"]'::jsonb,0,'Lab tests identify drugs.','original'),
('127.758.d.13.B',4,'A confirmatory lab method often used to identify drugs is:','["a visual guess", "gas chromatography–mass spectrometry", "a taste test", "a coin flip"]'::jsonb,1,'GC-MS confirms identity.','original'),
('127.758.d.14.A',3,'An examiner compares scratches left by a screwdriver on a door frame with a suspect''s tool. This explains individual characteristics of:','["handwriting", "voice", "tool marks", "gait"]'::jsonb,2,'Tools leave unique marks.','original'),
('127.758.d.14.A',4,'A tool mark''s individual characteristics come from:','["the color of the tool", "the brand label", "the store it came from", "random wear and damage on the tool"]'::jsonb,3,'Wear makes marks unique.','original'),
('127.758.d.14.B',3,'A firearms examiner explains how pulling the trigger releases the hammer, strikes the primer and fires the round. This describes the:','["mechanism of modern firearms", "recipe of a meal", "motion of a planet", "path of a river"]'::jsonb,0,'Firing sequence.','original'),
('127.758.d.14.B',4,'In a firearm, the primer is struck by the:','["sight", "firing pin", "barrel", "magazine"]'::jsonb,1,'The firing pin ignites the primer.','original'),
('127.758.d.14.C',3,'Rifling grooves leave marks on a bullet and the breech leaves marks on a casing. This recognizes characteristics of:','["glass and wood", "paper and ink", "bullet and cartridge cases", "tires and rims"]'::jsonb,2,'Marks link ammunition to a weapon.','original'),
('127.758.d.14.C',4,'Spiral grooves inside a barrel that make a bullet spin are called:','["tapering", "chambering", "sighting", "rifling"]'::jsonb,3,'Rifling stabilizes a bullet.','original'),
('127.758.d.14.D',3,'A lab swabs a suspect''s hands and tests for barium, lead and antimony particles. This describes analysis for:','["gunshot residue", "hair color", "fingerprints", "fibers"]'::jsonb,0,'GSR indicates firearm discharge.','original'),
('127.758.d.14.D',4,'Gunshot residue samples are typically collected from a suspect''s:','["teeth", "hands", "shoes only", "hair only"]'::jsonb,1,'Hands are swabbed.','original'),
('127.758.d.14.E',3,'Cartridge casings from different scenes are imaged and searched in a national network to find links. This recognizes the information in the:','["library network", "weather network", "National Integrated Ballistic Information Network (NIBIN)", "school directory"]'::jsonb,2,'NIBIN links firearm crimes.','original'),
('127.758.d.14.E',4,'NIBIN helps investigators by:','["printing reports", "selling firearms", "testing alcohol", "linking ballistic evidence from different crimes"]'::jsonb,3,'Connects cases.','original'),
('127.758.d.15.A',3,'A medical examiner notes that a body has stiffened and calculates how long ago death likely occurred. This explains the process and timeline of:','["rigor mortis", "lividity only", "aging", "hair growth"]'::jsonb,0,'Rigor peaks and then fades.','original'),
('127.758.d.15.A',4,'Rigor mortis is the stiffening of muscles that begins:','["months later", "a few hours after death", "after one week", "immediately before death"]'::jsonb,1,'Onset in hours.','original'),
('127.758.d.15.B',3,'Blood settles in the lowest parts of the body and creates purple discoloration. This explains:','["rigor", "bruising from a fall", "post mortem lividity", "a rash"]'::jsonb,2,'Livor mortis indicates body position.','original'),
('127.758.d.15.B',4,'Lividity can help investigators determine whether a body was:','["drinking alcohol", "exercising", "fed recently", "moved after death"]'::jsonb,3,'Fixed lividity shows position.','original'),
('127.758.d.15.C',3,'An entomologist studies the insects and their life stages on a body to estimate time since death. This determines time of death using:','["entomology", "geology", "astronomy", "botany"]'::jsonb,0,'Insect development is a clock.','original'),
('127.758.d.15.C',4,'Forensic entomology often relies on the development stages of:','["ants only", "blowfly larvae", "bees", "butterflies"]'::jsonb,1,'Blowflies colonize quickly.','original'),
('127.758.d.15.D',3,'Students review old cases to see which methods were used to estimate time and cause of death. This uses:','["horoscopes", "rumors", "case studies", "fiction"]'::jsonb,2,'Cases show applied methods.','original'),
('127.758.d.15.D',4,'Determining cause of death in an investigation is typically the role of a:','["clerk", "bailiff", "jury", "medical examiner or coroner"]'::jsonb,3,'Medical examiners determine cause.','original'),
('127.758.d.16.A',3,'A report labels the person harmed as the victim, the person who calls police as the complainant, a person with knowledge as a witness and the accused as a suspect. This explains the terms as they apply to:','["an investigation", "a school", "a market", "a recipe"]'::jsonb,0,'Roles in a case.','original'),
('127.758.d.16.A',4,'A person who saw or heard events relevant to a crime is a:','["bailiff", "witness", "suspect", "juror"]'::jsonb,1,'Witnesses provide information.','original'),
('127.758.d.16.B',3,'An investigator talks with a witness to gather information and later questions a suspect to seek admissions. This demonstrates:','["teaching a class", "playing a game", "interviewing and interrogating during an investigation", "debating a rule"]'::jsonb,2,'Interviews gather info; interrogations seek confessions.','original'),
('127.758.d.16.B',4,'An interview differs from an interrogation because it is:','["always secret", "always recorded", "always aggressive", "non-accusatory and aimed at gathering information"]'::jsonb,3,'Interviews are information gathering.','original'),
('127.758.d.16.C',3,'An investigator uses open-ended questions, active listening and a calm tone to build rapport. This demonstrates:','["effective questioning and positive communication", "intimidation", "distraction", "interruption"]'::jsonb,0,'Rapport yields better information.','original'),
('127.758.d.16.C',4,'An open-ended question typically begins with:','["''Isn''t it true...''", "''Tell me about...''", "''Yes or no?''", "''Did you...''"]'::jsonb,1,'Open questions invite narrative.','original'),
('127.758.d.16.D',3,'Officers inform a suspect in custody of the right to remain silent and to an attorney before questioning. This analyzes the importance of:','["a school bell", "a coupon", "reading the Miranda warnings", "a ballgame"]'::jsonb,2,'Miranda protects Fifth Amendment rights.','original'),
('127.758.d.16.D',4,'Miranda warnings are required before:','["any conversation", "a traffic stop", "a photograph", "custodial interrogation"]'::jsonb,3,'Custody plus interrogation.','original'),
('127.758.d.16.E',3,'Investigators use simple words, a comfortable setting and often a trained specialist when speaking with a young witness. This describes techniques to interview:','["children and juveniles", "adult executives", "teachers", "retired officers"]'::jsonb,0,'Child interviews require care.','original'),
('127.758.d.16.E',4,'When interviewing a child, an investigator should avoid:','["a quiet setting", "leading or suggestive questions", "patience", "simple language"]'::jsonb,1,'Leading questions distort accounts.','original'),
('127.758.d.17.A',3,'A detective gathers statements from victims and witnesses to create a description of the suspect. This compiles:','["maps only", "recipes", "information provided by victims and witnesses", "weather"]'::jsonb,2,'Descriptions come from witnesses.','original'),
('127.758.d.17.A',4,'Descriptions of a suspect from different witnesses should be:','["kept secret", "combined without review", "thrown out", "compared for consistency and corroborated"]'::jsonb,3,'Corroboration improves reliability.','original'),
('127.758.d.17.B',3,'Footprints, fibers and tool marks at a scene are examined to infer who was there. This examines evidence to determine a:','["suspect''s characteristics or identity", "weather forecast", "jury''s size", "witness''s age"]'::jsonb,0,'Evidence points to a suspect.','original'),
('127.758.d.17.B',4,'Physical evidence from a scene can help establish:','["only the time of day", "who was present and what occurred", "nothing useful", "only the weather"]'::jsonb,1,'Evidence reconstructs events.','original'),
('127.758.d.17.C',3,'Detectives notice that a burglar always enters through a rear window and takes only jewelry. This identifies the suspect''s:','["class schedule", "hair color", "modus operandi", "birth date"]'::jsonb,2,'MO is a repeated method.','original'),
('127.758.d.17.C',4,'A suspect''s modus operandi is:','["a mailing address", "a school grade", "a signature tattoo", "a characteristic way of committing crimes"]'::jsonb,3,'MO is method of operation.','original'),
('127.758.d.17.D',3,'A witness picks eyes, nose and hairstyle from a computer program to build a face of a suspect. This analyzes:','["computerized composite sketch applications", "video games", "music software", "photo editing for fun"]'::jsonb,0,'Identi-Kit builds composites.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
